const shelf=ref([]),notebook=ref([]),revisionTitle=ref('A step toward the proof'),restoredRevision=ref(null);const profile=ref(null),profileAddress=ref(''),profileDraft=ref({displayName:'',bio:''}),commentSort=ref('top'),replyTo=ref(null);const operators=ref([]);const page=ref('markets'),config=ref(null),list=ref([]),wallet=ref(devWallet(0)),role=ref(0),account=ref(devAccounts[0].address),sessionAddress=ref(''),observedBlock=ref('0'),portfolio=ref(null),allocation=ref(null),gov=ref(null),activity=ref(null),jobs=ref([]),comments=ref([]),busy=ref(''),notice=ref(''),error=ref(''),lastTx=ref(''),search=ref(''),filter=ref('All topics'),selectedId=ref(''),detailTab=ref('overview'),comment=ref('');
const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'—';const amount=x=>Number(formatEther(BigInt(x??0))).toLocaleString('en-US',{maximumFractionDigits:3});const time=x=>new Date(Number(x)*1000).toLocaleString();
