const form=ref({title:'',description:'',source:'import Init\n\nnamespace Oncm\n\ndef goal : Prop := ∀ a b : Nat, a + b = b + a\ntheorem solution : goal := Nat.add_comm\n\nend Oncm\n',tag:'Foundations',kind:'0',operatorId:'',parameters:'0x',dependency:'',expected:'1',deadline:'',funding:'100',fee:'2'});const palomarResults=ref(null),palomarQuery=ref('');const published=ref([]),importedPackage=ref(null),editingComment=ref(''),editCommentText=ref(''),moderationReason=ref('');const packageJSON=ref('');const registration=ref(null),trade=ref({side:0,mode:'buy',amount:'10',slippage:'1'}),quote=ref(null),lpAmount=ref('100'),setAmount=ref('10'),proofSource=ref(''),proofCertificate=ref(''),proofOutcome=ref('1'),allocationText=ref(''),newGov=ref({title:'Approve a new verification profile',profileId:'',verifier:'',manifestHash:'',kind:'profile',enabled:false}),importRef=ref('');
