watch(()=>form.value.source,()=>{externalImportEpoch++;registration.value=null;},{flush:'sync'});
watch(externalArtifactText,()=>{externalImportEpoch++;registration.value=null;proofCertificate.value='';proofBinding.value=null;},{flush:'sync'});
watch(page,()=>{externalImportEpoch++;},{flush:'sync'});
watch([proofOutcome,proofSource],()=>{externalImportEpoch++;proofSelection.begin();proofCertificate.value='';proofBinding.value=null;},{flush:'sync'});
const walletScope=createWalletScope(),sessionToken=ref(''),walletMode=ref('local'),socialContextEpoch=ref(0);
const defaultForm=structuredClone({...form.value});
let detachInjected=()=>{},injectedProvider=null,logoutTask=Promise.resolve(),signinTask=null,actionSerial=0;
const request=createSessionClient({scope:walletScope,getToken:()=>sessionToken.value,encode:stringify,fetchImpl:fetch});
const api=(url,options={})=>request(`/api${url}`,options);
function clearPrivateContext(){
 const oldToken=sessionToken.value;
 externalImportEpoch++;socialContextEpoch.value++;walletScope.invalidate();proofSelection.begin();sessionToken.value='';sessionAddress.value='';signinTask=null;
 creationRecovery.value=null;lpSnapshot.value=null;treasury.value=null;allocationDraftEpoch.value=null;jobs.value=[];shelf.value=[];notebook.value=[];restoredRevision.value=null;revisionTitle.value='A step toward the proof';
 profile.value=null;profileAddress.value='';profileDraft.value={displayName:'',bio:''};comments.value=[];comment.value='';replyTo.value=null;editingComment.value='';editCommentText.value='';moderationReason.value='';
 form.value=structuredClone(defaultForm);registration.value=null;proofSource.value='';proofCertificate.value='';proofBinding.value=null;proofOutcome.value='1';externalArtifactText.value='';publishedRegistrationChoice.value='';publishedProofChoice.value='';
 importedPackage.value=null;packageJSON.value='';importRef.value='';palomarResults.value=null;palomarQuery.value='';quote.value=null;trade.value={side:0,mode:'buy',amount:'10',slippage:'1'};lpAmount.value='100';setAmount.value='10';allocationText.value='';
 newGov.value={title:'Approve a new verification profile',profileId:'',verifier:'',manifestHash:'',kind:'profile',enabled:false};portfolio.value=null;allocation.value=null;lastTx.value='';busy.value='';error.value='';notice.value='';
 if(['shelf','workbench','profile','create'].includes(page.value))page.value='markets';
 if(oldToken)logoutTask=logoutTask.catch(()=>{}).then(()=>fetch('/api/auth/logout',{method:'POST',credentials:'omit',headers:{Authorization:`Bearer ${oldToken}`}})).catch(()=>{});
 return walletScope.capture();
}
async function refresh(){const ticket=walletScope.capture(),owner=account.value;const d=await api('/markets');list.value=d.markets;observedBlock.value=d.observedBlock;
 if(owner){portfolio.value=await api(`/portfolio/${owner}`);allocation.value=await api(`/allocations?account=${owner}`);}
 gov.value=await api('/governance');operators.value=await api('/operators');treasury.value=await api('/treasury');
 if(sessionAddress.value)try{jobs.value=visibleOwnerJobs(await api('/jobs'),owner);}catch(e){if(isStaleWalletError(e))throw e;if(e.statusCode===401&&walletScope.current(ticket))clearPrivateContext();else throw e;}}
async function act(label,fn){const ticket=walletScope.capture(),serial=++actionSerial;busy.value=label;error.value='';notice.value='';try{const result=await fn();walletScope.assert(ticket);if(result?.transactionHash)lastTx.value=result.transactionHash;notice.value=`${label} completed`;await refresh();return result;}catch(e){if(!isStaleWalletError(e)&&walletScope.current(ticket)){error.value=e.shortMessage??e.message;console.error(e);}}finally{if(walletScope.current(ticket)&&serial===actionSerial)busy.value='';}}
const send=(address,name,fn,args=[],options={})=>{const ticket=walletScope.capture(),signer=wallet.value;if(!signer||!account.value)throw Error('Connect a wallet on Agora chain 31371 first');return transact(signer,address,config.value.abis[name],fn,args,0n,{...options,assertCurrent:()=>walletScope.assert(ticket)});};
async function signout(){clearPrivateContext();await refresh();}
async function switchRole(){detachInjected();detachInjected=()=>{};injectedProvider=null;clearPrivateContext();walletMode.value='local';wallet.value=devWallet(Number(role.value));account.value=wallet.value.account.address;await refresh();}
async function reconcileInjected(accounts){const provider=injectedProvider,ticket=clearPrivateContext();wallet.value=null;account.value='';walletMode.value='injected';role.value='injected';
 if(!provider)return;
 const chainId=await walletScope.wait(provider.request({method:'eth_chainId'}),ticket);
 const addresses=accounts??await walletScope.wait(provider.request({method:'eth_accounts'}),ticket);walletScope.assert(ticket);
 if(Number(chainId)!==chain.id){error.value='Injected wallet network changed. Switch back to Agora chain 31371 and reconnect.';return;}
 if(!Array.isArray(addresses)||!isAddress(addresses[0]??'')){notice.value='Injected wallet disconnected. Private drafts and session cleared.';return;}
 wallet.value=injectedWalletForAccount(provider,addresses[0]);account.value=addresses[0];await refresh();
}
function injectedError(e){if(!isStaleWalletError(e))error.value=e.message;}
async function connect(){try{const provider=window.ethereum;if(!provider)throw Error('No injected wallet found. Use the clearly labelled local test wallet.');
 detachInjected();clearPrivateContext();wallet.value=null;account.value='';walletMode.value='injected';role.value='injected';injectedProvider=provider;
 const ticket=walletScope.capture();
 await walletScope.wait(provider.request({method:'wallet_addEthereumChain',params:[{chainId:'0x7a8b',chainName:chain.name,nativeCurrency:chain.nativeCurrency,rpcUrls:chain.rpcUrls.default.http}]}),ticket);
 await walletScope.wait(provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x7a8b'}]}),ticket);
 await walletScope.wait(provider.request({method:'eth_requestAccounts'}),ticket);
 detachInjected=bindInjectedEvents(provider,{accountsChanged:a=>reconcileInjected(a).catch(injectedError),chainChanged:()=>reconcileInjected().catch(injectedError),disconnect:()=>{clearPrivateContext();wallet.value=null;account.value='';}});
 await reconcileInjected();
 }catch(e){injectedError(e);}}
async function signin(){if(sessionToken.value&&sessionAddress.value?.toLowerCase()===account.value.toLowerCase())return;
 if(signinTask)return signinTask;
 const ticket=walletScope.capture(),owner=account.value,signer=wallet.value;if(!signer||!isAddress(owner))throw Error('Connect a wallet on Agora chain 31371 first');
 const task=(async()=>{await walletScope.wait(logoutTask,ticket);const {message}=await api('/auth/challenge',{method:'POST',body:{address:owner}});
 const signature=await walletScope.wait(signer.signMessage({message}),ticket);const result=await api('/auth/verify',{method:'POST',body:{message,signature}});walletScope.assert(ticket);
 if(result.address?.toLowerCase()!==owner.toLowerCase()||typeof result.token!=='string')throw Error('Unexpected SIWE session identity');sessionToken.value=result.token;sessionAddress.value=owner;})();
 signinTask=task;try{await task;}finally{if(signinTask===task)signinTask=null;}
}
function openMarket(m){proofSelection.select(m.id);proofCertificate.value='';proofBinding.value=null;selectedId.value=m.id;page.value='detail';detailTab.value='overview';proofSource.value=m.metadata.source??m.metadata.goal??'';quote.value=null;}
async function startJob(action,source=form.value.source){if(action!=='check')throw Error('Prepare certificates externally and import the resulting JSON. Web certificate generation is planned for later.');const epoch=walletScope.capture(),owner=account.value,target=selected.value,outcome=Number(proofOutcome.value),ticket=action==='prove'?proofSelection.begin():null;
 await signin();walletScope.assert(epoch);const job=await api('/jobs',{method:'POST',body:{action,source,statementId:action==='prove'?target?.id:undefined,goalHash:action==='prove'?target?.goalHash:undefined,fixtureId:action==='prove'?target?.metadata.fixtureId:runnerFixtureId(importedPackage.value),profileId:action==='prove'?target?.profileId:config.value.profileId,outcome}});
 if(!visibleOwnerJobs([job],owner).length)throw Error('Job response does not belong to the signed-in wallet');jobs.value.unshift(job);
 const poll=async()=>{try{walletScope.assert(epoch);jobs.value=visibleOwnerJobs(await api('/jobs'),owner);const {job:j,state}=polledJobState(jobs.value,job.id);
 if(state==='pending'){walletScope.schedule(poll,1500,epoch);return;}
 if(state==='missing'){notice.value='This job is no longer available to the current session; polling stopped.';return;}
 if(state==='succeeded'){if(!j.result)throw Error('Completed job has no result');if(action==='register'&&j.input.source===form.value.source)registration.value=j.result;
 if(action==='prove'&&proofSelection.current(ticket)){proofCertificate.value=j.result.certificate??'';proofBinding.value={statementId:ticket.statementId,goalHash:j.result.goalHash,profileId:j.result.profileId,outcome:Number(j.input.outcome),certificate:proofCertificate.value};}
 notice.value=`${action} job completed — inspect its result below`;
 }else error.value=j.diagnostics||`Job ${j.status}; polling stopped.`;
 }catch(e){if(!isStaleWalletError(e)&&walletScope.current(epoch)){if(e.statusCode===401)clearPrivateContext();else error.value=e.message;}}};walletScope.schedule(poll,800,epoch);return job;}
const creationDerivedReview=computed(()=>derivedReview({kind:Number(form.value.kind),dependencyId:form.value.dependency,deadlineInput:form.value.deadline,targetOutcome:form.value.expected,markets:list.value}));
async function resolveDerivedFromState(){const id=selectedId.value;const outcome=await walletScope.wait(pc.readContract({address:config.value.registry,abi:config.value.abis.AgoraRegistry,functionName:'derivedOutcome',args:[id]}));if(selectedId.value!==id)throw Error('Market selection changed');if(Number(outcome)===0)throw Error('Pending: the dependency is still open and this deadline has not expired. No resolution transaction was sent.');return send(config.value.registry,'AgoraRegistry','resolveDerived',[id]);}
async function createMarket(){if(creationRecovery.value&&!creationRecovery.value.complete){await act('Resume interrupted creation',continueCreation);return;}await act('Create statement and market',async()=>{const f={...form.value};const derivedArgs=['1','2','3'].includes(f.kind)?reviewedDerivedArguments(creationDerivedReview.value):null;const funding=parseEther(f.funding),fee=parseFeePercent(f.fee);const reg=registration.value;if(f.kind==='0'&&!reg?.registrationCertificate)throw new Error('Import and verify an externally prepared registration certificate first.');if(f.kind==='0'&&reg?.status==='verified-external'){const current=await api(`/certificate-profiles/${reg.profileId}`);if(!current.enabled)throw new Error('Install this distinct profile through Governance first.');if(f.source!==reg.source)throw new Error('The source no longer matches the imported certificate.');}const m=await api('/metadata',{method:'POST',body:{title:f.title,description:f.description,source:f.source,tag:f.tag,goalHash:reg?.goalHash,externalRef:importRef.value||null,files:importedPackage.value?.files??{},fixtureId:runnerFixtureId(importedPackage.value),provenance:importedPackage.value?.provenance,externalCertificate:reg?.generic?{format:'oncm-external-certificate-bundle-v1',bundleSha256:reg.bundleSha256,goalExportSha256:reg.goalExport.sha256,goalExportBytes:reg.goalExport.bytes,sourceSha256:reg.sourceSha256,sourceOrigin:reg.sourceOrigin,sourceGoalRelation:'not-verified',profileId:reg.profileId}:null}});const registerCall=f.kind==='0'?{method:'register',args:[reg.goalHash,reg.profileId??config.value.profileId,m.uri,reg.registrationCertificate]}:f.kind==='4'?{method:'registerCustom',args:[f.operatorId,f.dependency,f.parameters,m.uri]}:{method:'registerDerived',args:[...derivedArgs,m.uri]};
creationRecovery.value=newCreation({owner:account.value,registry:config.value.registry,token:config.value.token,funding,fee,title:f.title,registerCall});return continueCreation();});}
async function continueCreation(){const state=creationRecovery.value,ticket=walletScope.capture();if(!state)throw Error('No interrupted creation in this tab');
 try{const result=await resumeCreation(state,{owner:account.value,registry:config.value.registry,send,assertCurrent:()=>walletScope.assert(ticket),receipt:hash=>walletScope.wait(pc.waitForTransactionReceipt({hash}),ticket),event:(receipt,name,address,contract)=>{const decoded=receipt.logs.filter(l=>l.address.toLowerCase()===address.toLowerCase()).flatMap(l=>{try{return[decodeEventLog({abi:config.value.abis[contract],data:l.data,topics:l.topics})]}catch{return[]}}).find(e=>e.eventName===name);if(!decoded)throw Error('Creation receipt is missing '+name);return decoded.args;},allowance:spender=>walletScope.wait(pc.readContract({address:config.value.token,abi:config.value.abis.TrueToken,functionName:'allowance',args:[state.owner,spender]}),ticket)});await refresh();selectedId.value=state.statementId;page.value='detail';return result;
 }catch(error){if(walletScope.current(ticket)&&state.statementId){await refresh().catch(()=>{});selectedId.value=state.statementId;}throw error;}}
async function openCreationResult(){await refresh();const m=list.value.find(m=>m.id===creationRecovery.value?.statementId);if(m)openMarket(m);}
async function getQuote(){if(!pool.value)throw new Error('Create and fund a pool first');const args=[parseEther(trade.value.amount),Number(trade.value.side)];quote.value=await walletScope.wait(pc.readContract({address:pool.value.address,abi:config.value.abis.FixedProductMarketMaker,functionName:trade.value.mode==='buy'?'calcBuyAmount':'calcSellAmount',args}));}
async function executeTrade(){await act(trade.value.mode==='buy'?'Buy position':'Sell position',async()=>{await getQuote();const p=pool.value.address;const input=parseEther(trade.value.amount);const bps=parseSlippagePercent(trade.value.slippage);const deadline=BigInt(Math.floor(Date.now()/1000)+600);if(trade.value.mode==='buy'){await send(config.value.token,'TrueToken','approve',[p,input]);return send(p,'FixedProductMarketMaker','buyWithDeadline',[input,Number(trade.value.side),quote.value*(10000n-bps)/10000n,deadline]);}await send(config.value.ctf,'ConditionalTokens','setApprovalForAll',[p,true]);return send(p,'FixedProductMarketMaker','sellWithDeadline',[input,Number(trade.value.side),(quote.value*(10000n+bps)+9999n)/10000n,deadline]);});}
const lpPreviews=computed(()=>{if(!lpSnapshot.value)return{};let n;try{n=parseEther(lpAmount.value)}catch(e){return{error:e.message}};const result={};try{result.deposit=fundingPreview(lpSnapshot.value,n)}catch(e){result.depositError=e.message}try{result.withdraw=withdrawalPreview(lpSnapshot.value,n)}catch(e){result.withdrawError=e.message}return result;});
const setLimits=computed(()=>{const yes=BigInt(selectedPosition.value?.yes??0),no=BigInt(selectedPosition.value?.no??0);return{yes,no,t:BigInt(portfolio.value?.t??0),merge:yes<no?yes:no};});
function setAllowed(merge){try{completeSetPreview(setLimits.value,parseEther(setAmount.value),merge);return true}catch{return false}}
watch([selectedId,account],()=>{lpSnapshot.value=null;});
async function loadLPPreview(){if(!pool.value)throw Error('Create the pool first');const target=pool.value.address,owner=account.value;const snap=await walletScope.wait(readLiquiditySnapshot({client:pc,pool:target,owner,abi:config.value.abis.FixedProductMarketMaker}));if(pool.value?.address!==target||account.value!==owner)throw Error('Selected market changed during preview');lpSnapshot.value=snap;return snap;}
async function createMissingPool(){await act('Create empty pool',()=>send(config.value.registry,'AgoraRegistry','createPool',[selected.value.id,parseFeePercent('2')]));}
async function liquidity(remove=false){await act(remove?'Withdraw liquidity':'Provide liquidity',async()=>{const n=parseEther(lpAmount.value),before=remove?lpPreviews.value.withdraw:lpPreviews.value.deposit;if(!before)throw Error('Refresh and review the LP preview first');const p=pool.value.address;const snap=await loadLPPreview(),latest=remove?withdrawalPreview(snap,n):fundingPreview(snap,n);if(stringify(before)!==stringify(latest))throw Error('Pool amounts changed. Review the refreshed preview and submit again.');if(remove)return send(p,'FixedProductMarketMaker','removeFunding',[n]);await send(config.value.token,'TrueToken','approve',[p,n]);if(pool.value?.address!==p)throw Error('Market selection changed after approval');return send(p,'FixedProductMarketMaker','addFunding',[n,[]]);});}
async function completeSet(merge=false){await act(merge?'Merge complete set':'Split complete set',async()=>{const n=parseEther(setAmount.value),target=selected.value,owner=account.value;completeSetPreview(setLimits.value,n,merge);const blockNumber=await walletScope.wait(pc.getBlockNumber()),read=(address,abi,args)=>walletScope.wait(pc.readContract({address,abi,functionName:'balanceOf',args,blockNumber}));const [yes,no,t]=await Promise.all([read(config.value.ctf,config.value.abis.ConditionalTokens,[owner,target.positionIds[0]]),read(config.value.ctf,config.value.abis.ConditionalTokens,[owner,target.positionIds[1]]),read(config.value.token,config.value.abis.TrueToken,[owner])]);completeSetPreview({yes,no,t},n,merge);if(selectedId.value!==target.id)throw Error('Market selection changed');if(!merge)await send(config.value.token,'TrueToken','approve',[config.value.ctf,n]);if(selectedId.value!==target.id)throw Error('Market selection changed after approval');return send(config.value.ctf,'ConditionalTokens',merge?'mergePositions':'splitPosition',[config.value.token,zeroHash,target.conditionId,[1n,2n],n]);});}
async function redeem(){await act('Redeem settled positions',()=>send(config.value.ctf,'ConditionalTokens','redeemPositions',[config.value.token,zeroHash,selected.value.conditionId,[1n,2n]]));}
async function openShelf(){await act('Open research shelf',async()=>{await signin();shelf.value=await api('/shelf');page.value='shelf';});}
async function saveBookmark(id,notes){await act('Save to research shelf',async()=>{await signin();await api(`/shelf/${id}`,{method:'PUT',body:{notes}});shelf.value=await api('/shelf');});}
async function removeBookmark(id){await act('Remove from shelf',async()=>{await api(`/shelf/${id}`,{method:'DELETE'});shelf.value=await api('/shelf');});}
async function loadNotebook(){await act('Open notebook history',async()=>{await signin();notebook.value=await api('/notebook');});}
async function saveRevision(){await act('Save Lean revision',async()=>{await signin();const r=await api('/notebook',{method:'POST',body:{title:revisionTitle.value,source:form.value.source,profileId:config.value.profileId,basedOn:restoredRevision.value}});restoredRevision.value=r.id;notebook.value=await api('/notebook');});}
function restoreRevision(r){form.value.source=r.source;restoredRevision.value=r.id;revisionTitle.value=r.title+' · continued';page.value='workbench';notice.value='Revision restored into the editor; the saved snapshot is unchanged';}
function socialReceipt(r){lastTx.value=r.transactionHash;observedBlock.value=String(r.blockNumber);notice.value='Social transaction confirmed';}
async function openProfile(address){profileAddress.value=address;page.value='profile';}
async function submitProof(){await act('Submit verified certificate',()=>{assertProofBinding(proofBinding.value,selected.value,proofOutcome.value,proofCertificate.value);return send(config.value.registry,'AgoraRegistry','submitProof',[selectedId.value,Number(proofOutcome.value),proofCertificate.value]);});}
watch(allocationText,text=>{if(text.trim()&&allocationDraftEpoch.value===null)allocationDraftEpoch.value=allocation.value?.epoch??null;});
async function prepareGovernanceShare(){await act('Prepare governance beneficiary draft',async()=>{allocation.value=await api(`/allocations?account=${account.value}`);const rows=governanceShareDraft(allocation.value,config.value.timelock,governancePercent.value);allocationDraftEpoch.value=allocation.value.epoch;allocationText.value=rows.map(r=>`${r.address} ${sharePercent(r.share)}`).join('\n');});}
async function rebaseAllocationDraft(){await act('Review current allocation baseline',async()=>{allocation.value=await api(`/allocations?account=${account.value}`);allocationDraftEpoch.value=allocation.value.epoch;});}
async function prepareTreasuryConsent(p,approve){await act('Prepare governance consent draft',async()=>{allocation.value=await api(`/allocations?account=${account.value}`);const current=allocation.value.proposals.find(x=>x.id===p.id);if(!current?.active||!current.requiredConsents.some(c=>isTreasury(c.address)))throw Error('This allocation is inactive or does not decrease the treasury share');newGov.value={title:`${approve?'Approve':'Revoke'} governance beneficiary consent for allocation #${p.id}`,kind:'allocation-consent',proposalId:String(p.id),approve};page.value='governance';});}
function prepareTreasuryTransfer(){newGov.value={title:'Distribute treasury T through Safe and Timelock',kind:'treasury-transfer',recipient:'',amount:''};page.value='governance';}
async function proposeAllocation(){await act('Propose allocation',async()=>{const review=allocationDraftReview(allocationText.value,allocation.value);if(!review?.valid)throw Error(review?.error??'Prepare an allocation first');const epoch=allocationDraftEpoch.value;allocation.value=await api(`/allocations?account=${account.value}`);if(String(epoch)!==String(allocation.value.epoch))throw Error('Allocation epoch changed; refresh and review the draft baseline before proposing');const rows=review.rows.filter(r=>r.share>0n).sort((a,b)=>a.address.toLowerCase().localeCompare(b.address.toLowerCase()));return send(config.value.allocation,'AllocationController','propose',[BigInt(epoch),rows.map(r=>r.address),rows.map(r=>r.share),BigInt(allocation.value.observedAt)+86400n]);});}
async function applyAllocation(id){await act('Apply allocation',async()=>{allocation.value=await api(`/allocations?account=${account.value}`);const current=allocation.value.proposals.find(p=>p.id===id);if(!current?.canApply)throw new Error('Allocation is not ready: refresh the required consents and expiry.');return send(config.value.allocation,'AllocationController','execute',[BigInt(id)]);});}
async function prepareOperator(){const code=await walletScope.wait(pc.getCode({address:config.value.operatorCandidate}));newGov.value={title:'Add resolved_after operator version 1',kind:'operator',profileId:keccak256(toHex('AGORA_RESOLVED_AFTER_V1')),verifier:config.value.operatorCandidate,manifestHash:keccak256(code),enabled:true};}
async function createGovernance(){const ticket=walletScope.capture(),draftEpoch=governanceDraftEpoch,draft={...newGov.value},configuration=config.value;
 const assertDraft=()=>{walletScope.assert(ticket);if(draftEpoch!==governanceDraftEpoch||configuration!==config.value)throw Error('Governance draft changed; review the current exact call again');};
 await act('Propose protocol update',async()=>{assertDraft();if(draft.kind==='treasury-transfer'){const fresh=await api('/treasury');assertDraft();treasury.value=fresh;assertTreasuryFunds(governanceTreasuryCall(draft,configuration,configuration.abis),fresh);}await signin();assertDraft();return api('/governance',{method:'POST',body:{...draft,profileId:draft.profileId||configuration.profileId}});});}
async function signGovernance(p){await act('Sign council proposal',async()=>{gov.value=await api('/governance');p=gov.value.proposals.find(x=>x.id===p.id);if(!p?.canSign)throw new Error('Proposal is already scheduled, executed or has a stale Safe nonce.');const signature=await walletScope.wait(wallet.value.signMessage({message:{raw:p.safeHash}}));return api(`/governance/${p.id}/signatures`,{method:'POST',body:{signature}});});}
async function scheduleGovernance(p){await act('Schedule Safe decision',async()=>{gov.value=await api('/governance');p=gov.value.proposals.find(x=>x.id===p.id);if(!p?.canSchedule)throw new Error('Proposal cannot be scheduled: refresh its signatures, Safe nonce and timelock state.');const signatures='0x'+[...p.signatures].sort((a,b)=>a.address.toLowerCase().localeCompare(b.address.toLowerCase())).map(s=>s.signature.slice(2,-2)+(parseInt(s.signature.slice(-2),16)+4).toString(16).padStart(2,'0')).join('');return send(config.value.safe,'Safe','execTransaction',[config.value.timelock,0n,p.scheduleData,0,0n,0n,0n,zeroAddress,zeroAddress,signatures]);});}
async function executeGovernance(p){await act('Execute timelocked update',async()=>{gov.value=await api('/governance');p=gov.value.proposals.find(x=>x.id===p.id);if(!p?.canExecute)throw new Error('Timelock is not ready in the latest block. Wait or use the local devnet time button, then refresh.');return send(config.value.timelock,'AgoraTimelock','execute',[p.target,0n,p.data,zeroHash,p.salt]);});}
async function refreshGovernance(){gov.value=await api('/governance');}
async function advanceGovernanceTime(){await act('Advance local devnet by10seconds',async()=>{await signin();await api('/dev/advance-time',{method:'POST'});gov.value=await api('/governance');});}
async function loadActivity(){page.value='activity';activity.value=await api('/activity');}
function download(name,value){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([stringify(value)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
async function refreshAdditionalProfile(){additionalProfile.value=await api('/additional-profile');if(registration.value?.status==='verified-external'){const current=registration.value;const state=await api(`/certificate-profiles/${current.profileId}`);if(registration.value===current)registration.value={...current,enabled:state.enabled};}}
async function loadPublishedCertificateChoice(settlement=false){await act('Load published certificate JSON',async()=>{const id=settlement?publishedProofChoice.value:publishedRegistrationChoice.value;if(!id)throw new Error('Choose a published certificate first');if(settlement){proofSelection.begin();proofCertificate.value='';proofBinding.value=null;}else registration.value=null;const loaded=await api(`/published-certificates/${encodeURIComponent(id)}`);externalArtifactText.value=JSON.stringify(loaded.artifact,null,2);});}
async function importExternalCertificate(artifact,settlement=false,pendingTicket,pendingEpoch,rawInput){const ticket=settlement?(pendingTicket??proofSelection.begin()):null,importEpoch=pendingEpoch??++externalImportEpoch;if(settlement){proofCertificate.value='';proofBinding.value=null;}else registration.value=null;await act('Verify external certificate onchain',async()=>{
 const generic=artifact?.format==='oncm-external-certificate-bundle-v1';const result=await api(generic?'/certificates/import-bundle':'/certificates/import',{method:'POST',body:generic?{bundle:rawInput??artifact,statementId:settlement?ticket.statementId:undefined}:{artifact,statementId:settlement?ticket.statementId:undefined}});
 if(importEpoch!==externalImportEpoch)throw Error('Source, artifact or view changed during verification; import the current bundle again.');
 if(settlement){if(!proofSelection.current(ticket))throw Error('Selected market changed while verifying; import again.');if(result.outcome===0)throw Error('Registration certificate cannot resolve a statement');proofOutcome.value=String(result.outcome);proofCertificate.value=result.certificate;proofBinding.value={statementId:ticket.statementId,goalHash:result.goalHash,profileId:result.profileId,outcome:result.outcome,certificate:result.certificate};return;}
 if(result.outcome!==0)throw Error('Use the Proof tab to import a settlement certificate');form.value.kind='0';form.value.source=result.source;
 form.value.title=result.generic?(result.metadata.title||`Lean goal ${result.goalHash.slice(0,12)}`):result.fixture.name==='true'?'Identity implication · zero-axiom Lean logic':'Every proposition holds · zero-axiom Lean logic';
 form.value.description=result.generic?(result.metadata.description||'The canonical goal export is cryptographically verified. Any attached source is provenance, not a verified rendering of the goal.'):result.fixture.name==='true'?'For every proposition P, P implies P. Distinct perf05 profile; no Nat arithmetic claim.':'For every proposition P, P holds (∀ P : Prop, P). A refutation proves that this universal assertion implies False; distinct perf05 profile.';
 form.value.tag='Foundations';importedPackage.value=null;importRef.value='';registration.value=result;page.value='create';await refreshAdditionalProfile();
 });}
async function importExternalFile(event,settlement=false){const file=event.target.files?.[0];if(!file)return;if(settlement){proofCertificate.value='';proofBinding.value=null;}else registration.value=null;if(file.size>EXTERNAL_BUNDLE_LIMITS.wrapper){error.value='External bundle JSON must be at most 2 MiB';return;}const epoch=++externalImportEpoch,ticket=settlement?proofSelection.begin():undefined;try{const raw=await walletScope.wait(file.text());if(epoch!==externalImportEpoch)throw Error('File selection changed; import again');await importExternalCertificate(parseBoundedJSON(raw),settlement,ticket,epoch,raw);}catch(e){injectedError(e);}event.target.value='';}
async function importExternalText(settlement=false){try{await importExternalCertificate(parseBoundedJSON(externalArtifactText.value),settlement,undefined,undefined,externalArtifactText.value);}catch(e){error.value=e.message;}}
async function prepareAdditionalProfile(){await act('Prepare additional profile governance',async()=>{await refreshAdditionalProfile();if(!additionalProfile.value.proposal)throw new Error('Deploy the immutable bridge first');newGov.value={...additionalProfile.value.proposal};page.value='governance';});}
async function exportPackage(){download('agora-statement.json',await api(`/package/${selectedId.value}`));}
function applyPackage(raw){const draft=sourceDraft(raw);importedPackage.value={...draft.package,catalogVerified:published.value.includes(raw)};form.value.title=draft.title;form.value.source=draft.source;form.value.description=draft.description;form.value.kind='0';importRef.value=draft.externalRef;registration.value=draft.registration;notice.value=draft.integrity.notice;page.value='create';}
function applyPackageJSON(text){registration.value=null;if(new TextEncoder().encode(text).length>MAX_PACKAGE_BYTES)throw Error('Source package exceeds 16 MiB');applyPackage(JSON.parse(text));}
async function importPackage(event){const f=event.target.files?.[0];if(f)await act('Import formal package',async()=>{registration.value=null;if(f.size>MAX_PACKAGE_BYTES)throw Error('Source package exceeds 16 MiB');applyPackageJSON(await walletScope.wait(f.text()));});event.target.value='';}
async function importPastedPackage(){await act('Import pasted formal package',async()=>applyPackageJSON(packageJSON.value));}
async function searchExternal(){await act('Search Palomar registry',async()=>palomarResults.value=await api(`/palomar?q=${encodeURIComponent(palomarQuery.value)}`));}
async function usePalomar(entry){await act('Import Palomar snapshot',async()=>applyPackage(await api('/import/palomar',{method:'POST',body:{id:entry.id,version:entry.version}})));}
async function importRepository(){await act('Import exact repository snapshot',async()=>applyPackage(await api('/import/snapshot',{method:'POST',body:{url:importRef.value}})));}
onUnmounted(()=>{detachInjected();walletScope.invalidate();});
onMounted(async()=>{try{config.value=await api('/config');published.value=await api('/fixtures');await refreshAdditionalProfile();await refresh();allocationText.value=allocation.value.recipients.map((a,i)=>`${a} ${Number(allocation.value.shares[i])/10000}`).join('\n');}catch(e){injectedError(e);} });
</script>

<template>
<div class="app-shell">
 <aside class="sidebar"><a class="wordmark" href="/"><span class="brand-symbol">∴</span> agora<span class="brand-dot">.</span></a><div class="eyebrow sidebar-caption">A MARKET FOR MATHEMATICAL TRUTH</div>
 <nav><button :class="{active:page==='markets'||page==='detail'}" @click="page='markets'"><span>▦</span> Explore statements</button><button :class="{active:page==='create'}" @click="page='create'"><span>＋</span> Create a market</button><button :class="{active:page==='workbench'}" @click="page='workbench'"><span>λ</span> Lean workbench</button><button :class="{active:page==='portfolio'}" @click="page='portfolio'"><span>◈</span> My positions</button><button :class="{active:page==='shelf'}" @click="openShelf"><span>▱</span> Research shelf</button><button :class="{active:page==='profile'}" @click="openProfile(account)"><span>○</span> My profile</button><div class="nav-divider"></div><button :class="{active:page==='governance'}" @click="page='governance'"><span>◎</span> Governance</button><button :class="{active:page==='revenue'}" @click="page='revenue'"><span>↗</span> Protocol revenue</button><button :class="{active:page==='activity'}" @click="loadActivity"><span>≋</span> Chain activity</button></nav>
 <div class="sidebar-note"><div class="tiny-dot"></div> Agora local network<span>CHAIN 31371 · REAL TRANSACTIONS</span><p>Every outcome settles from a verified proof or a deterministic chain record.</p></div>
 </aside>
 <div class="workspace"><header class="topbar"><span class="top-crumb">Research commons <span>/</span> {{page==='detail'?'Statement':page==='markets'?'Explore':page.replace(/^./,x=>x.toUpperCase())}}</span><div class="wallet-area"><span class="network"><i></i> Block {{observedBlock}}</span><select aria-label="Local test wallet" :disabled="!!busy" v-model="role" @change="switchRole"><option v-if="walletMode==='injected'" value="injected">Injected wallet</option><option v-for="(name,i) in config?.roles" :value="i">Test wallet: {{name}}</option></select><button v-if="sessionAddress" @click="signout">Sign out &amp; clear drafts</button><button class="wallet-button" @click="connect">{{short(account)}} <span>↗</span></button></div></header>
 <div class="status-strip" v-if="busy||error||notice" :class="{error:!!error}"><span>{{busy?`◌ ${busy}…`:error||`✓ ${notice}`}}</span><button v-if="lastTx" @click="loadActivity">Inspect transaction {{short(lastTx)}} ↗</button><button v-if="!busy" @click="error='';notice=''">×</button></div>
 <main v-if="config">
 <section v-if="page==='markets'">
  <div class="page-heading"><div><div class="eyebrow">THE OPEN MATHEMATICS EXCHANGE</div><h1>Good questions.<br><em>Provable answers.</em></h1><p class="intro">Discover formal statements, back an idea, or bring a proof.<br>Markets are open to everyone. Mathematics has the final word.</p></div><div class="hero-formula"><span>∀ ε &gt; 0</span><div class="formula-line"></div><strong>uncertainty → proof</strong><small>LEAN VERIFIED · ONCHAIN SETTLEMENT</small></div></div>
  <div class="stats-grid"><div><span>OPEN STATEMENTS</span><strong>{{list.filter(m=>m.outcome===0).length}} <small>questions worth exploring</small></strong></div><div><span>LP SHARE SUPPLY</span><strong>{{totalLPShares.toLocaleString()}} <small>shares across pools · not T value</small></strong></div><div><span>SETTLED ONCHAIN</span><strong>{{list.filter(m=>m.outcome!==0).length}} <small>verified outcomes</small></strong></div></div>
  <div class="section-heading"><h2>Explore the frontier</h2><button class="text-button" @click="page='create'">Create a statement <span>＋</span></button></div><div class="filterbar"><label class="search"><span>⌕</span><input v-model="search" placeholder="Search a theorem, topic, or idea…" aria-label="Search statements"></label><select v-model="filter"><option>All topics</option><option>Number theory</option><option>Foundations</option><option>Algebra</option><option>Analysis</option><option>Derived markets</option></select><span>{{filtered.length}} statements</span></div>
  <div class="market-grid" v-if="filtered.length"><article class="market-card" v-for="(m,i) in filtered" :key="m.id" @click="openMarket(m)"><div class="card-top"><span class="tag">{{m.metadata.tag||'Foundations'}}</span><span class="state" :class="{settled:m.outcome!==0}"><i></i>{{m.outcome===0?'Open':m.outcome===1?'True':'False'}}</span></div><div class="math-symbol">{{m.kind?'t ≤ d':i%3===0?'ℙ → ∞':i%3===1?'a² + b²':'∀ n ∈ ℕ'}}</div><h3>{{m.metadata.title}}</h3><p>{{m.metadata.description}}</p><div class="card-market"><div><strong>{{m.outcome===0?probability(m):m.outcome===1?'100%':'0%'}}</strong><span>{{m.outcome===0?'market confidence':'final payout'}}</span></div><div class="mini-chart"><i v-for="n in 12" :style="{height:`${12+(n*7+i*11)%35}px`}"></i></div></div><div class="card-footer"><span>{{amount(m.pools[0]?.totalSupply)}} LP shares</span><b>View market ↗</b></div></article></div>
  <div v-else class="empty-state"><span class="empty-math">∃ P</span><h3>The next question begins with you.</h3><p>No formal market has been registered on this chain yet.<br>Import a published Lean problem or prepare your own statement.</p><button class="primary" @click="page='create'">Create the first market ↗</button></div>
  <div class="research-note"><span>01 / HOW IT WORKS</span><div><h3>A statement is a commitment.</h3><p>The formal goal, proof profile and collateral are fixed onchain. Every T creates a complete YES + NO set. A valid certificate releases the winning collateral.</p></div><button @click="page='workbench'">Open the workbench ↗</button></div>
 </section>

 <section v-else-if="page==='detail'&&selected">
  <button class="text-button back" @click="page='markets'">← All statements</button><div class="detail-heading"><div><span class="tag">{{selected.metadata.tag}}</span><h1>{{selected.metadata.title}}</h1><p>{{selected.metadata.description}}</p></div><div class="confidence"><strong>{{selected.outcome===0?probability(selected):selected.outcome===1?'100%':'0%'}}</strong><span>{{selected.outcome===0?'Market confidence':selected.outcome===1?'Resolved TRUE':'Resolved FALSE'}}</span></div></div>
  <div class="meta-row"><button @click="openProfile(selected.creator)">By {{short(selected.creator)}} ↗</button><span>Statement {{short(selected.id)}}</span><span>Pool {{short(pool?.address)}}</span><button @click="exportPackage">↓ Export package</button><button @click="saveBookmark(selected.id)">☆ Save to shelf</button></div>
  <div class="tabs"><button v-for="t in ['overview','trade','liquidity','proof','discussion']" :class="{active:detailTab===t}" @click="detailTab=t">{{t.replace(/^./,x=>x.toUpperCase())}}</button></div>
  <div class="two-col" v-if="detailTab==='overview'"><div class="panel"><div class="panel-heading"><h2>{{selected.kind?'The onchain predicate':selected.metadata.externalCertificate?'Attached Lean source · unverified rendering':'The formal statement'}}</h2><span>{{selected.kind?'Registry state':'Lean'}}</span></div><pre v-if="!selected.kind" class="lean-code">{{selected.metadata.source??selected.metadata.goal??'Derived onchain predicate'}}</pre><p v-if="selected.kind" class="research-note">{{derivedRuleText(selected)}}</p><p v-if="!selected.kind&&selected.metadata.externalCertificate" class="research-note">This source and description are supplied provenance. Source-to-goal relation: <strong>not verified</strong>. The certificate commits to exact goal-export bytes, SHA256 {{selected.metadata.externalCertificate.goalExportSha256}}. Source SHA256: {{selected.metadata.externalCertificate.sourceSha256||'not attached'}}.</p><p v-if="!selected.kind" class="muted">The goal commitment includes the foundation and environment selected by its proof profile. Human descriptions are supplementary.</p><div class="identity-grid"><label>GOAL HASH<code>{{selected.goalHash}}</code></label><label>PROFILE<code>{{selected.profileId}}</code></label><label>CONDITION<code>{{selected.conditionId}}</code></label></div><div v-if="selected.kind"><p>Derived rule {{selected.kind}} · dependency {{short(selected.dependency)}} · deadline {{selected.deadline==='0'?'none':time(selected.deadline)}}</p><button class="primary" :disabled="busy||selected.outcome!==0" @click="act('Resolve derived statement',resolveDerivedFromState)">Resolve from chain state</button></div></div><aside class="panel"><h2>Your position</h2><div class="balance-row"><span>YES</span><strong>{{amount(selectedPosition?.yes)}}</strong></div><div class="balance-row"><span>NO</span><strong>{{amount(selectedPosition?.no)}}</strong></div><div class="balance-row"><span>Pool shares</span><strong>{{amount(selectedPosition?.lp[0]?.balance)}}</strong></div><button class="primary full" @click="detailTab='trade'" v-if="selected.outcome===0">Trade this statement ↗</button><button class="primary full" @click="redeem" v-else>Redeem settled positions</button><hr><h3>Complete outcome sets</h3><p class="muted">Lock 1 T to create 1 YES + 1 NO. Merge equal amounts of both sides to recover T.</p><p>Available T: {{exactAmount(setLimits.t)}}. Matched YES + NO available to merge: {{exactAmount(setLimits.merge)}}.</p><p>Requested {{setAmount}}: split locks that many T and returns the same number of each outcome; merge burns equal YES and NO and returns that many T. Amounts use exact base units.</p><label>AMOUNT T<input v-model="setAmount" type="text" inputmode="decimal" min="0" step="0.1"></label><div class="button-row"><button :disabled="busy||!setAllowed(false)" @click="completeSet(false)">Split T</button><button :disabled="busy||!setAllowed(true)" @click="completeSet(true)">Merge set</button></div></aside></div>
  <div class="two-col" v-if="detailTab==='trade'"><div class="panel trade-panel"><h2>Take a position</h2><p class="muted">Swaps execute directly in the Gnosis fixed product market maker.</p><div class="segmented"><button :class="{active:trade.mode==='buy'}" @click="trade.mode='buy';quote=null">Buy</button><button :class="{active:trade.mode==='sell'}" @click="trade.mode='sell';quote=null">Sell for T</button></div><div class="outcome-selector"><button :class="{active:trade.side===0}" @click="trade.side=0;quote=null">YES <span>{{probability(selected)}}</span></button><button :class="{active:trade.side===1}" @click="trade.side=1;quote=null">NO <span>{{probability(selected,1)}}</span></button></div><label>{{trade.mode==='buy'?'T TO SPEND':'T TO RECEIVE'}}<input v-model="trade.amount" type="text" inputmode="decimal" min="0" @input="quote=null"></label><label>SLIPPAGE LIMIT %<input v-model="trade.slippage" type="text" inputmode="decimal" min="0" max="20"></label><div class="quote"><span>{{trade.mode==='buy'?'Estimated outcome received':'Estimated outcome spent'}}</span><strong>{{quote===null?'—':amount(quote)}}</strong></div><div class="button-row"><button @click="act('Calculate quote',getQuote)">Preview</button><button class="primary" :disabled="busy||selected.outcome!==0" @click="executeTrade">{{trade.mode==='buy'?'Buy':'Sell'}} {{trade.side===0?'YES':'NO'}} ↗</button></div><p v-if="selected.outcome!==0" class="notice">This FPMM has settled. Trading and new funding are stopped; withdrawal and redemption remain available.</p></div><div class="panel"><h2>Know the terms</h2><div class="balance-row"><span>Trading fee</span><strong>{{Number(pool?.fee??0)/1e16}}%</strong></div><div class="balance-row"><span>To liquidity providers</span><strong>80% of fee</strong></div><div class="balance-row"><span>Protocol revenue</span><strong>20% of fee</strong></div><p class="muted">The protocol portion is transferred in T to the current immutable epoch during this transaction. Confirmation is required for approvals and the swap.</p></div></div>
  <div class="two-col" v-if="detailTab==='liquidity'"><div class="panel"><h2>Support a liquid market</h2><p class="muted">The FPMM creates the necessary conditional positions from your T. An imbalanced pool can return residual outcome tokens.</p><label>AMOUNT — T TO ADD / LP SHARES TO REMOVE<input v-model="lpAmount" type="text" inputmode="decimal" min="0"></label><button v-if="!pool" :disabled="busy||selected.outcome!==0" @click="createMissingPool">Create empty pool · 2% trading fee</button><button v-else :disabled="!!busy" @click="act('Refresh LP preview',loadLPPreview)">Refresh LP preview</button><div v-if="lpSnapshot" class="research-note"><p>Snapshot block {{lpSnapshot.blockNumber}} · pool {{lpSnapshot.pool}}</p><p v-if="lpPreviews.deposit">Deposit {{exactAmount(lpPreviews.deposit.t)}} T → {{exactAmount(lpPreviews.deposit.shares)}} LP shares; returned YES {{exactAmount(lpPreviews.deposit.returned[0])}}, NO {{exactAmount(lpPreviews.deposit.returned[1])}}.</p><p v-if="lpPreviews.withdraw">Withdraw {{exactAmount(lpPreviews.withdraw.shares)}} LP shares → YES {{exactAmount(lpPreviews.withdraw.returned[0])}}, NO {{exactAmount(lpPreviews.withdraw.returned[1])}}; accrued T fees {{exactAmount(lpPreviews.withdraw.tFees)}} are also released.</p><p v-if="lpPreviews.error||lpPreviews.withdrawError">{{lpPreviews.error||lpPreviews.withdrawError}}</p><p>Exact original FPMM floor divisions. Estimates can change before mining; the original funding methods do not accept a minimum-output bound.</p></div><div class="button-row"><button class="primary" :disabled="busy||selected.outcome!==0||!lpPreviews.deposit" @click="liquidity(false)">Provide liquidity</button><button :disabled="busy||!lpPreviews.withdraw" @click="liquidity(true)">Withdraw LP shares</button></div><button class="text-button" v-if="pool" @click="act('Claim LP trading fees',()=>send(pool.address,'FixedProductMarketMaker','withdrawFees',[account]))">Claim accrued LP fees ↗</button></div><div class="panel"><h2>Pool inventory</h2><div class="balance-row"><span>YES reserve</span><strong>{{amount(pool?.balances[0])}}</strong></div><div class="balance-row"><span>NO reserve</span><strong>{{amount(pool?.balances[1])}}</strong></div><div class="balance-row"><span>Your LP shares</span><strong>{{amount(selectedPosition?.lp[0]?.balance)}}</strong></div><p class="muted">Withdrawal returns the current composition of reserves. Receiving all value in T depends on merging, redemption or an available trade.</p></div></div>
  <div v-if="detailTab==='proof'" class="two-col"><div class="panel"><h2>Bring the proof</h2><p class="muted">Prepare the ZK certificate externally, then import its JSON here. The optional native Lean check below does not generate a certificate.</p><label>PROVE THE OUTCOME<select v-model="proofOutcome"><option value="1">TRUE — prove P</option><option value="2">FALSE — prove ¬P</option></select></label><textarea class="code-input" v-model="proofSource" rows="12"></textarea><div class="button-row"><button :disabled="selected.profileId===additionalProfile?.profileId" @click="act('Check Lean',()=>startJob('check',proofSource))">Check Lean</button></div></div><div class="panel"><h2>Submit the certificate</h2><p v-if="selected.profileId===additionalProfile?.profileId" class="muted">This market uses perf05. Import its compatible external CI result; the native checker available here uses v3.</p><label>PUBLISHED CI SETTLEMENT<select v-model="publishedProofChoice"><option value="">Choose a proof or refutation</option><option v-for="choice in additionalProfile?.publishedCertificates?.filter(c=>c.outcome!==0)" :key="choice.id" :value="choice.id" :disabled="choice.goalHash!==selected.goalHash||choice.profileId!==selected.profileId">{{choice.label}}</option></select></label><button :disabled="busy||!publishedProofChoice" @click="loadPublishedCertificateChoice(true)">Load published settlement JSON</button><p class="muted">Load does not accept the proof. Verify it below before the separate wallet submission.</p><label class="file-button">Verify imported certificate / bundle JSON<input type="file" accept=".json" @change="importExternalFile($event,true)"></label><details open><summary>Review or paste external proof artifact JSON</summary><textarea class="code-input" v-model="externalArtifactText" rows="4"></textarea><button :disabled="busy||!externalArtifactText" @click="importExternalText(true)">Verify & load settlement certificate</button></details><label>VERIFIABLE CERTIFICATE · HEX<textarea class="code-input" v-model="proofCertificate" rows="7" placeholder="0x…"></textarea></label><button class="primary full" :disabled="busy||!proofCertificate||selected.outcome!==0" @click="submitProof">Verify & settle onchain ↗</button><p class="muted">There is no admin resolution method. Invalid goals, outcomes and certificates are rejected by the contract.</p><div class="job" v-for="j in jobs.filter(j=>j.input.statementId===selected.id)"><b>{{j.input.action}} · {{j.status}}</b><pre>{{j.diagnostics}}</pre><button v-if="j.result" @click="download('agora-proof.json',j.result)">Download result</button></div></div></div>
  <div class="panel discussion" v-if="detailTab==='discussion'"><OnchainSocial :config="config" :wallet="wallet" :account="account" :context-epoch="socialContextEpoch" :statement-id="selected.id" @transaction="socialReceipt" @open-profile="openProfile" /></div>
 </section>

 <section v-else-if="page==='create'" class="narrow-page"><div class="eyebrow">START WITH A PRECISE QUESTION</div><h1>Create a statement.</h1><div v-if="creationRecovery" class="panel research-note"><h2>{{creationRecovery.complete?'Creation completed':'Interrupted creation · resume confirmed steps'}}</h2><p>{{creationRecovery.title}} · owner {{creationRecovery.owner}}</p><p>Initial funding {{exactAmount(creationRecovery.funding)}} T · fee {{exactAmount(creationRecovery.fee)}} fraction. Changing the form does not change this saved action.</p><p v-if="creationRecovery.statementId">Registered statement {{creationRecovery.statementId}}</p><p v-if="creationRecovery.pool">Pool {{creationRecovery.pool}}</p><p v-for="(receipt,step) in creationRecovery.receipts" :key="step">{{step}} confirmed · {{receipt.transactionHash}}</p><p v-if="creationRecovery.pending">Awaiting {{creationRecovery.pending.step}} receipt {{creationRecovery.pending.hash}}. Resume inspects this transaction before sending anything else.</p><button v-if="!creationRecovery.complete" :disabled="!!busy" @click="act('Resume interrupted creation',continueCreation)">Resume remaining creation steps</button><button v-if="creationRecovery.statementId" :disabled="!!busy" @click="act('Open registered market',openCreationResult)">Open registered market</button><button v-if="!creationRecovery.pending" :disabled="!!busy" @click="creationRecovery=null">Clear checklist · existing market stays onchain</button><p>This checklist stays in this tab. After reload, open the registered market from Explore and use its Liquidity controls; do not register it again.</p></div><p class="intro">Fix the formal goal. Open a market. Let anyone work toward a proof.</p><div class="panel"><h2>01 <span>The question</span></h2><label>TITLE<input v-model="form.title" placeholder="A concise name for your statement"></label><div class="form-grid"><label>TOPIC<select v-model="form.tag"><option>Foundations</option><option>Number theory</option><option>Algebra</option><option>Analysis</option><option>Derived markets</option></select></label><label>STATEMENT TYPE<select v-model="form.kind"><option value="0">Lean mathematical goal</option><option value="1">Resolved by a deadline</option><option value="2">Resolves to an outcome</option><option value="3">Resolves to an outcome by deadline</option><option value="4">Governance-approved operator</option></select></label></div><label>HUMAN DESCRIPTION<textarea v-model="form.description" rows="3" placeholder="What does this question ask, and why does it matter?"></textarea></label><template v-if="form.kind==='0'"><div v-if="importedPackage?.sourceOnly" class="research-note"><b>{{importedPackage.catalogVerified?'Ix · imported-source':'Imported source package'}}</b><p>{{importedPackage.mathKind}}</p><p>Imported snapshot native validation: {{importedPackage.catalogVerified?(importedPackage.validation?.nativeLabel??'not yet complete'):'not verified; any included validation metadata is a claim'}}. ZK: not generated. No market has been registered by this import.</p><a :href="importedPackage.repositoryUrl" target="_blank" rel="noreferrer">Exact upstream declaration ↗</a><p><code>{{importedPackage.commit}}</code></p><button @click="page='workbench'">Open this draft in Lean workbench</button></div><div v-if="registration?.status==='verified-external'" class="research-note"><b>{{registration.generic?registration.profileLabel:'Imported perf05 · zero axioms'}}</b><p>{{registration.profileId}}</p><p>Verified by the immutable onchain bridge. {{registration.enabled?'Governance enabled this profile.':'New registrations are disabled or installation is pending.'}} The v3 and perf05 profiles remain distinct.</p><p v-if="registration.generic">Canonical goal export SHA256: <code>{{registration.goalExport.sha256}}</code> ({{registration.goalExport.bytes}} bytes). Source-to-goal relation: <strong>not verified</strong>. Source SHA256: {{registration.sourceSha256||'no source attached'}}.</p><p v-if="registration.sourceOrigin">Source provenance claim: {{registration.sourceOrigin.repository}} · {{registration.sourceOrigin.commit}} · {{registration.sourceOrigin.path}} · {{registration.sourceOrigin.declaration}}</p></div><p class="muted">The native checker uses <code>Oncm.goal : Prop</code> and <code>Oncm.solution</code> under v3. Prepare the registration certificate externally, then import and verify its JSON below. Changing the source clears the accepted certificate.</p><label>LEAN SOURCE<textarea v-model="form.source" rows="8" class="code-input"></textarea></label><div class="button-row"><button :disabled="busy||registration?.status==='verified-external'" @click="act('Check Lean source',()=>startJob('check'))">Check Lean only · no ZK</button><span class="good" v-if="registration?.registrationCertificate">✓ Registration certificate ready</span></div><p class="muted" v-if="!config.proofAvailable">The real proof bridge is not installed in this deployment yet. A compatible bridge is required before registration or settlement.</p></template><template v-else><label>DEPENDENCY<select v-model="form.dependency"><option value="">Choose a registered statement</option><option v-for="m in list" :value="m.id">{{m.metadata.title}}</option></select></label><label v-if="form.kind==='4'">OPERATOR VERSION<select v-model="form.operatorId"><option v-for="o in operators" :value="o.id">{{o.id}}</option></select></label><label v-if="form.kind==='4'">ENCODED OPERATOR PARAMETERS<textarea class="code-input" v-model="form.parameters"></textarea></label><label v-if="form.kind!=='1'&&form.kind!=='4'">EXPECTED OUTCOME<select v-model="form.expected"><option value="1">TRUE</option><option value="2">FALSE</option></select></label><label v-if="form.kind!=='2'&&form.kind!=='4'">DEADLINE · YOUR LOCAL TIME<input v-model="form.deadline" type="text" placeholder="2030-01-01 00:00:00" autocomplete="off"></label><div v-if="creationDerivedReview" class="research-note"><h3>Review exact derived statement</h3><p v-if="!creationDerivedReview.valid">{{creationDerivedReview.error}}</p><template v-else><p>{{creationDerivedReview.type}} · kind {{creationDerivedReview.kind}}</p><p>Dependency {{creationDerivedReview.dependencyTitle}} · <code>{{creationDerivedReview.dependencyId}}</code></p><p>Outcome requirement: {{creationDerivedReview.targetLabel}} ({{creationDerivedReview.targetOutcome}})</p><p v-if="creationDerivedReview.deadline">Local {{creationDerivedReview.deadline.local}}<br>UTC {{creationDerivedReview.deadline.utc}}<br>Unix seconds {{creationDerivedReview.deadline.unix}}</p><p v-else>No deadline (Unix0).</p><p>Initial liquidity {{form.funding}} T · trading fee {{form.fee}}%. Registration and pool creation are separate wallet transactions; zero funding performs no transfer of T.</p></template></div></template></div><div class="panel"><h2>02 <span>The market</span></h2><div class="form-grid"><label>INITIAL LIQUIDITY · T<input v-model="form.funding" type="text" inputmode="decimal" min="0"></label><label>TRADING FEE %<input v-model="form.fee" type="text" inputmode="decimal" min="0" max="10" step=".1"></label></div><p class="muted">Your T creates complete conditional sets in Gnosis CTF. You receive FPMM liquidity shares. Future protocol fees are paid into immutable allocation epochs.</p><button class="primary full" :disabled="busy||(creationRecovery&&!creationRecovery.complete)||(creationDerivedReview&&!creationDerivedReview.valid)||!form.title||(form.kind==='0'&&(!registration?.registrationCertificate||(registration?.status==='verified-external'&&!registration?.enabled)))" @click="createMarket">Register statement & create market ↗</button></div><div class="panel"><h2>Import an externally generated certificate</h2><p class="muted">Prepare certificates outside the website. Import a generic oncm-external-certificate-bundle-v1 containing full goal-export bytes and a compatible v3 or perf05 certificate (maximum 2 MiB JSON). Any goal accepted by the supported immutable profile can be verified; it does not need to appear in the example catalogue. The original EVM verifier and bridge check the claim. Attached Lean source is byte-checked provenance; source-to-goal correspondence is not verified. You can also load one of the published CI results below.</p><p>Profile {{additionalProfile?.profileId}} · {{additionalProfile?.enabled?'Enabled for registration':'Governance installation pending'}}</p><div class="button-row"><button :disabled="busy||!additionalProfile?.proposal||additionalProfile?.enabled" @click="prepareAdditionalProfile">Prepare governance installation</button><button :disabled="!!busy" @click="act('Refresh profile status',refreshAdditionalProfile)">Refresh profile status</button></div><label>PUBLISHED CI REGISTRATION<select v-model="publishedRegistrationChoice"><option value="">Choose a goal registration</option><option v-for="choice in additionalProfile?.publishedCertificates?.filter(c=>c.outcome===0)" :key="choice.id" :value="choice.id">{{choice.label}}</option></select></label><button :disabled="busy||!publishedRegistrationChoice" @click="loadPublishedCertificateChoice(false)">Load published registration JSON</button><p class="muted">Load fills the JSON field only. Verify it below, then register through your wallet.</p><label class="file-button">Import external certificate / bundle JSON<input type="file" accept=".json" @change="importExternalFile($event)"></label><details open><summary>Review or paste registration certificate JSON</summary><textarea class="code-input" v-model="externalArtifactText" rows="5"></textarea><button :disabled="busy||!externalArtifactText" @click="importExternalText(false)">Verify & use registration</button></details></div><div class="panel"><h2>Import an existing formalization</h2><div v-if="importedPackage?.integrity" class="research-note"><p>{{importedPackage.integrity.notice}} Source keccak256: <code>{{importedPackage.integrity.sourceHash}}</code></p><p v-if="importedPackage.statementId">Imported statement context: <code>{{importedPackage.statementId}}</code> · chain {{importedPackage.chainId}}. This import creates no new onchain entry.</p><p v-if="importedPackage.profileId">Imported profile commitment: <code>{{importedPackage.profileId}}</code></p><p v-if="importedPackage.goalHash">Imported goal commitment: <code>{{importedPackage.goalHash}}</code>. Source-to-goal relation: not verified. Certificate: not accepted by package import.</p></div><label>SEARCH RECENT PALOMAR ENTRIES<input v-model="palomarQuery" placeholder="Theorem, title, or topic"></label><button @click="searchExternal" :disabled="!!busy">Search live Palomar registry</button><div v-if="palomarResults"><small>{{palomarResults.scope}} · {{palomarResults.entries.length}} matches</small><article class="published-fixture" v-for="e in palomarResults.entries"><h3>{{e.title}}</h3><p>{{e.abstract}}</p><code>{{e.source.commit}}</code><button @click="usePalomar(e)" :disabled="!!busy">Import formalization draft</button></article></div><article class="published-fixture" v-for="f in published" :key="f.id"><h3>{{f.title}}</h3><p>{{f.description}}</p><p v-if="f.sourceOnly"><b>imported-source</b> · Native: {{f.validation?.nativeLabel??'not yet complete'}} · ZK: not generated</p><p><code>{{f.commit}}</code></p><p v-if="f.sourceOnly"><a :href="f.repositoryUrl" target="_blank" rel="noreferrer">{{f.upstreamDeclaration}} ↗</a> · {{f.version}}</p><button class="primary" @click="applyPackage(f)">{{f.sourceOnly?'Import Ix source draft ↗':'Use this published Lean task ↗'}}</button></article><p>Use a content-addressed package or an exact published repository snapshot. External registry status is informative; the protocol checks its own certificates.</p><label>REPOSITORY / PALOMAR REFERENCE<input v-model="importRef" placeholder="https://github.com/owner/repository/blob/40-char-commit/Statement.lean"></label><button @click="importRepository" :disabled="!!busy||!importRef">Fetch exact snapshot</button><label class="file-button">Import package JSON<input type="file" accept=".json" @change="importPackage"></label><details><summary>Paste a portable package JSON</summary><label>PORTABLE PACKAGE JSON<textarea v-model="packageJSON" rows="6" class="code-input"></textarea></label><button :disabled="busy||!packageJSON" @click="importPastedPackage">Import pasted package as draft</button><p class="muted">Same schema and exact file/source hash checks as file import. Maximum 16 MiB. A package restores a draft; any certificate requires separate cryptographic verification.</p></details><a class="text-button" href="https://palomar-registry.org/" target="_blank" rel="noreferrer">Explore Palomar ↗</a></div><div class="job" v-for="j in jobs.filter(x=>x.input.action==='register')"><b>Registration · {{j.status}}</b><pre>{{j.diagnostics}}</pre></div></section>

 <section v-else-if="page==='workbench'"><div class="eyebrow">A PLACE TO THINK FORMALLY</div><h1>Lean workbench.</h1><p class="intro">Edit and check Lean source without generating ZK proofs. Prepare certificates externally; use their JSON in Create a market or the market’s Proof tab.</p><div class="two-col"><div class="panel"><div class="panel-heading"><h2>Solution.lean</h2><span>PINNED PROOF PROFILE</span></div><textarea class="code-input tall" v-model="form.source"></textarea><div class="button-row"><button @click="act('Check Lean source',()=>startJob('check'))">Run Lean check</button><button class="primary" @click="page='create'">Import prepared certificate ↗</button><button @click="download('agora-source.json',{source:form.source,profileId:config.profileId})">Export</button></div></div><div class="panel"><h2>Lean notebook</h2><p class="muted">Save private immutable revisions under your wallet. Restoring a revision changes the editor; it does not rewrite earlier snapshots.</p><label>REVISION TITLE<input v-model="revisionTitle"></label><div class="button-row"><button @click="saveRevision" :disabled="!!busy">Save source revision</button><button @click="loadNotebook" :disabled="!!busy">Load my revisions</button><button v-if="notebook.length" @click="download('agora-notebook.json',notebook)">Export notebook</button></div><article class="notebook-revision" v-for="r in notebook"><b>{{r.title}}</b><small>{{new Date(r.createdAt).toLocaleString()}}</small><code>{{short(r.sourceHash)}}</code><button @click="restoreRevision(r)">Restore into editor</button></article><hr><h2>Computation journal</h2><p class="muted">A successful Lean check does not resolve a market. Every accepted settlement also requires an EVM-verified certificate.</p><div v-if="!jobs.length" class="subtle-empty">Native checks and existing job history appear here. Certificate generation from the website is planned for later.</div><div v-for="j in jobs" class="job"><div><b>{{j.input.action}} · {{j.status}}</b><small>{{new Date(j.createdAt).toLocaleTimeString()}}</small></div><pre>{{j.diagnostics || (j.status === 'succeeded' ? (j.result?.status === 'checked' ? 'Lean and the pinned checker accepted the proof. No zk certificate was requested.' : 'Certificate generated. Download the verified result below.') : ['queued','running'].includes(j.status) ? 'Waiting for the isolated runner…' : j.status === 'cancelled' ? 'Job cancelled.' : 'Job failed; inspect the result for details.')}}</pre><button v-if="j.result" @click="download('agora-result.json',j.result)">Download artifact</button><button v-if="['queued','running'].includes(j.status)" @click="act('Cancel job',()=>api(`/jobs/${j.id}/cancel`,{method:'POST'}))">Cancel</button></div></div></div></section>

 <section v-else-if="page==='portfolio'"><div class="eyebrow">YOUR RESEARCH CAPITAL</div><h1>My positions.</h1><p class="intro">{{short(account)}} · Balances read directly from the Agora chain.</p><div class="stats-grid"><div><span>AVAILABLE TRUE</span><strong>{{amount(portfolio?.t)}} <small>T</small></strong></div><div><span>GAS BALANCE</span><strong>{{amount(portfolio?.eth)}} <small>test ETH</small></strong></div><div><span>TEST NETWORK ONLY</span><button class="text-button" @click="act('Receive local test funds',()=>api('/faucet',{method:'POST',body:{address:account}}))">Get 1,000 test T ↗</button></div></div><div class="panel"><h2>Statement positions</h2><table><thead><tr><th>Statement</th><th>YES</th><th>NO</th><th>LP shares</th><th>Status</th></tr></thead><tbody><tr v-for="p in portfolio?.positions" @click="openMarket(p)"><td>{{p.metadata.title}}</td><td>{{amount(p.yes)}}</td><td>{{amount(p.no)}}</td><td>{{amount(p.lp[0]?.balance)}}</td><td>{{p.outcome===0?'Open':p.outcome===1?'True':'False'}} ↗</td></tr></tbody></table><p v-if="!portfolio?.positions.length" class="subtle-empty">Trade a statement or provide liquidity to begin.</p></div></section>

 <section v-else-if="page==='shelf'"><div class="eyebrow">QUESTIONS TO RETURN TO</div><h1>Research shelf.</h1><p class="intro">Your saved statements and private research notes.<br>Only your signed-in wallet can read or edit this shelf.</p><div class="two-col"><article class="panel" v-for="item in shelf"><div class="panel-heading"><h2>{{list.find(m=>m.id===item.statementId)?.metadata.title??short(item.statementId)}}</h2><span>{{list.find(m=>m.id===item.statementId)?.outcome===0?'OPEN':'SETTLED'}}</span></div><code>{{short(item.statementId)}}</code><label>PRIVATE NOTES<textarea v-model="item.notes" maxlength="10000" rows="5" placeholder="An approach to try, a useful reference, a question for later…"></textarea></label><div class="button-row"><button @click="saveBookmark(item.statementId,item.notes)" :disabled="!!busy">Save notes</button><button class="primary" @click="openMarket(list.find(m=>m.id===item.statementId))">Open statement ↗</button><button @click="removeBookmark(item.statementId)" :disabled="!!busy">Remove</button></div></article></div><div class="panel subtle-empty" v-if="!shelf.length">Save a statement from its overview to build your reading list.</div></section>

 <section v-else-if="page==='profile'" class="narrow-page"><OnchainSocial :config="config" :wallet="wallet" :account="account" :context-epoch="socialContextEpoch" :profile-address="profileAddress" @transaction="socialReceipt" @open-profile="openProfile" /><button @click="page='markets'">Explore statements ↗</button></section>

 <section v-else-if="page==='revenue'"><div class="eyebrow">CONSENT, MADE EXPLICIT</div><h1>Protocol revenue.</h1><p class="intro">Every fee belongs to the allocation epoch active at its trade.<br>A smaller share requires that beneficiary’s own consent.</p><div class="two-col"><div class="panel"><div class="panel-heading"><h2>Current allocation</h2><span>EPOCH {{allocation?.epoch}}</span></div><div class="balance-row" v-for="(a,i) in allocation?.recipients"><span>{{isTreasury(a)?'Governance treasury':short(a)}} <small v-if="a.toLowerCase()===account.toLowerCase()">you</small></span><strong>{{Number(allocation.shares[i])/10000}}%</strong></div><h3 class="spaced">Propose a new allocation</h3><p class="muted">One address and percentage per line. Total must be 100%. Only addresses whose share decreases must approve.</p><label>GOVERNANCE SHARE DRAFT · %<input v-model="governancePercent" inputmode="decimal"></label><button :disabled="!!busy" @click="prepareGovernanceShare">Add governance beneficiary to draft</button><p class="muted">Uses the current allocation, proportionally scales other shares, and does not submit. Treasury: {{config.timelock}}. Exact rounding uses allocation base units.</p><textarea class="code-input" v-model="allocationText" rows="5"></textarea><button :disabled="!!busy" @click="rebaseAllocationDraft">Refresh and review draft baseline</button><div v-if="allocationReview" class="research-note"><p>Draft baseline epoch {{allocationDraftEpoch}} · current epoch {{allocation?.epoch}} · block {{allocation?.observedBlock}}</p><p v-if="!allocationReview.valid" class="bad">{{allocationReview.error}}</p><template v-else><h3>Review all beneficiaries</h3><p v-for="r in allocationReview.rows" :key="r.address"><code>{{r.address}}</code> {{isTreasury(r.address)?'Governance treasury':''}} · {{sharePercent(r.previous)}}% → {{sharePercent(r.share)}}% <strong :class="r.loses?'bad':'good'">{{r.loses?'Consent required':'No decrease'}}</strong></p></template></div><button class="primary" :disabled="busy||!allocationReview?.valid||String(allocationDraftEpoch)!==String(allocation?.epoch)" @click="proposeAllocation">Propose allocation</button></div><div class="panel"><h2>Your fee claims</h2><div class="epoch" v-for="e in allocation?.epochs"><div><b>Epoch {{e.epoch}}</b><code>{{short(e.split)}}</code><p>{{amount(e.balance)}} T held in immutable splitter</p></div><div><strong>{{amount(e.claimable)}} T</strong><button :disabled="busy||BigInt(e.claimable)===0n" @click="act('Claim epoch revenue',()=>send(e.split,'PaymentSplitter','release',[config.token,account]))">Claim T ↗</button></div></div><p class="muted">Payments use the original OpenZeppelin PaymentSplitter. Historical epochs are independent; current share changes do not reassign old funds.</p></div></div><div class="panel" v-if="treasury"><h2>Governance treasury</h2><p>Safe council decisions execute from the Timelock beneficiary. Claims pay this address; distributions require a separate governance decision.</p><code>{{treasury.address}}</code><p>Token T · {{treasury.token}} · 18 decimals · block {{treasury.observedBlock}}</p><strong>{{exactAmount(treasury.balance)}} T held by treasury</strong><div v-for="e in treasury.epochs" :key="e.epoch" class="epoch"><div>Epoch {{e.epoch}} · share {{sharePercent(e.share)}}%<p>Claimable {{exactAmount(e.claimable)}} T · previously released {{exactAmount(e.released)}} T</p><code>{{e.split}}</code></div><button :disabled="busy||BigInt(e.claimable)===0n" @click="act('Claim revenue into governance treasury',()=>send(e.split,'PaymentSplitter','release',[config.token,config.timelock]))">Claim T into treasury</button></div><button :disabled="!!busy" @click="prepareTreasuryTransfer">Prepare treasury distribution</button></div><div class="panel"><h2>Allocation proposals</h2><p class="muted">Onchain snapshot · block {{allocation?.observedBlock}}. Consent is required from every address listed below.</p><button :disabled="!!busy" @click="act('Refresh allocation snapshot',refresh)">Refresh consent status</button><article class="proposal" v-for="p in allocation?.proposals"><div><b>Proposal #{{p.id}}</b><span>Base epoch {{p.baseVersion}} · {{p.status}}</span></div><div class="allocation-lines"><code v-for="(a,i) in p.payees">{{short(a)}} → {{Number(p.shares[i])/10000}}%</code></div><div class="allocation-lines"><h3>Required consents</h3><p v-if="!p.requiredConsents?.length">No beneficiary loses a share.</p><div v-for="c in p.requiredConsents" :key="c.address"><code>{{c.address}}</code><span> {{Number(c.previousShare)/10000}}% → {{Number(c.newShare)/10000}}% · </span><strong :class="c.approved?'good':'bad'">{{c.approved?'Consented':'Awaiting consent'}}</strong><template v-if="isTreasury(c.address)"><span> Governance executor · use council decision</span><button :disabled="busy||!p.active" @click="prepareTreasuryConsent(p,true)">Prepare governance consent</button><button :disabled="busy||!p.active" @click="prepareTreasuryConsent(p,false)">Prepare governance revocation</button></template></div></div><div class="button-row"><button :disabled="busy||!canConsent(p)" @click="act('Approve share decrease',()=>send(config.allocation,'AllocationController','setApproval',[BigInt(p.id),true]))">Give my consent</button><button :disabled="busy||!canConsent(p)" @click="act('Revoke consent',()=>send(config.allocation,'AllocationController','setApproval',[BigInt(p.id),false]))">Revoke</button><button class="primary" :disabled="busy||!p.canApply" @click="applyAllocation(p.id)">Apply</button></div></article><p class="subtle-empty" v-if="!allocation?.proposals.length">No allocation changes proposed.</p></div></section>

 <section v-else-if="page==='governance'"><div class="eyebrow">THE RULES OF THE COMMONS</div><h1>Governance.</h1><div class="research-note"><p>Snapshot block {{gov?.observedBlock}} · {{time(gov?.observedTimestamp??0)}}</p><div class="button-row"><button :disabled="!!busy" @click="act('Refresh governance',refreshGovernance)">Refresh governance</button><button v-if="gov?.localTimeControls" :disabled="!!busy" @click="advanceGovernanceTime">Local devnet: +10 seconds &amp; mine one block</button></div><p v-if="gov?.localTimeControls">Test chain31371 only. Advancing time does not execute a governance proposal.</p></div><p class="intro">A two-member Safe council schedules decisions through an OpenZeppelin timelock.<br>The council cannot resolve a theorem or bypass beneficiary consent.</p><div class="governance-summary"><div><label>SAFE COUNCIL</label><code>{{short(config.safe)}}</code></div><div><label>SIGNATURE THRESHOLD</label><strong>{{gov?.threshold}} of {{gov?.owners.length}}</strong></div><div><label>TIMELOCK</label><strong>{{gov?.delay}} seconds <small>local test setting</small></strong></div></div><div class="two-col"><div class="panel"><h2>Propose a protocol extension</h2><p class="muted">New verifier and operator versions are immutable. Disabling a profile retires new registrations; existing statements can still resolve under their pinned verifier.</p><details><summary>Available extension example</summary><p>ResolvedAfterOperator returns TRUE when its dependency settles strictly after the ABI-encoded uint64 deadline. Pending dependency stays unresolved.</p><code>{{config.operatorCandidate}}</code><button @click="prepareOperator">Prepare this operator proposal</button></details><label>TITLE<input v-model="newGov.title"></label><label>OPERATION<select v-model="newGov.kind"><option value="profile">Register a new verifier profile</option><option value="disable">Change registration availability</option><option value="operator">Approve a new operator version</option><option value="allocation-consent">Governance beneficiary consent / revoke</option><option value="treasury-transfer">Distribute T from governance treasury</option></select></label><template v-if="!['allocation-consent','treasury-transfer'].includes(newGov.kind)"><label>{{newGov.kind==='operator'?'OPERATOR VERSION ID':'PROFILE ID'}} · BYTES32<input v-model="newGov.profileId" :placeholder="config.profileId"></label><template v-if="newGov.kind!=='disable'"><label>{{newGov.kind==='operator'?'EVALUATOR':'VERIFIER'}} ADDRESS<input v-model="newGov.verifier" :placeholder="config.verifier"></label><label>BUILD MANIFEST HASH · BYTES32<input v-model="newGov.manifestHash" placeholder="0x…"></label></template><label class="checkbox" v-else><input v-model="newGov.enabled" type="checkbox">Enable new registrations</label></template><template v-if="newGov.kind==='allocation-consent'"><label>OUTER ALLOCATION PROPOSAL ID<input v-model="newGov.proposalId" inputmode="numeric"></label><label>DECISION<select v-model="newGov.approve"><option :value="true">Approve treasury share decrease</option><option :value="false">Revoke treasury consent</option></select></label><p>Controller {{config.allocation}} · executor {{config.timelock}} · chain31371</p><p v-if="consentTarget">Outer base epoch {{consentTarget.baseVersion}} · {{consentTarget.status}} · expires {{time(consentTarget.expiresAt)}}</p><p v-else class="bad">Choose an existing active allocation which decreases the treasury share.</p></template><template v-if="newGov.kind==='treasury-transfer'"><p>Token T · {{config.token}} · 18 decimals. Timelock holds {{exactAmount(treasury?.balance)}} T. This decision does not change external allocation shares.</p><label>RECIPIENT ADDRESS<input v-model="newGov.recipient" placeholder="0x…"></label><label>EXACT AMOUNT · T<input v-model="newGov.amount" inputmode="decimal" placeholder="0.0"></label></template><div v-if="treasuryCallPreview" class="research-note"><h3>Exact treasury decision</h3><p v-if="!treasuryCallPreview.valid" class="bad">{{treasuryCallPreview.error}}</p><template v-else><p>Executor {{config.timelock}} · target {{treasuryCallPreview.target}} · call value0wei</p><pre>{{stringify(treasuryCallPreview.action)}}</pre><pre>{{treasuryCallPreview.data}}</pre></template><p>Safe signatures schedule the exact call; the existing Timelock delay applies. An applied, stale or expired outer allocation cannot receive fresh consent.</p></div><button class="primary" @click="createGovernance" :disabled="busy||(treasuryCallPreview&&!treasuryCallPreview.valid)">Create proposal</button></div><div><article class="panel" v-for="p in gov?.proposals"><div class="panel-heading"><h2>{{p.title}}</h2><span>{{p.status?.replaceAll('-',' ').toUpperCase()}}</span></div><p v-if="p.scheduled">Ready at block time {{time(p.operationTimestamp)}} · {{p.ready?'delay elapsed':'waiting for a mined block'}}</p><p>{{p.signatureCount}} of {{gov.threshold}} council signatures · Safe nonce {{p.nonce}}</p><code class="block-code">Target {{p.target}}<br>Operation {{p.operationId}}</code><details><summary>Inspect exact calldata</summary><pre>{{p.data}}</pre><pre v-if="p.action">{{stringify(p.action)}}</pre><pre v-if="p.actionContext">{{stringify(p.actionContext)}}</pre></details><p v-if="p.actionError" class="bad">{{p.actionError}}</p><div class="button-row"><button :disabled="busy||!p.canSign||!gov.owners.some(a=>a.toLowerCase()===account.toLowerCase())" @click="signGovernance(p)">Sign</button><button :disabled="busy||!p.canSchedule" @click="scheduleGovernance(p)">Schedule via Safe</button><button class="primary" :disabled="busy||!p.canExecute" @click="executeGovernance(p)">Execute</button></div></article><div v-if="!gov?.proposals.length" class="panel subtle-empty">No protocol changes proposed.<br>Every decision will display its exact target and calldata here.</div></div></div></section>

 <section v-else-if="page==='activity'"><div class="page-title-row"><div><div class="eyebrow">THE CHAIN IS THE RECORD</div><h1>Activity explorer.</h1></div><button @click="loadActivity">Refresh ↻</button></div><p class="intro">Local chain 31371. Blocks, transaction receipts, actors and decoded asset movements.</p><div v-if="!activity" class="subtle-empty">Reading blocks…</div><article class="block-panel" v-for="b in activity?.blocks.filter(b=>b.transactions.length)"><div class="block-heading"><div><b>Block {{b.number}}</b><time>{{time(b.timestamp)}}</time></div><code>{{b.hash}}</code></div><div class="transaction" v-for="t in b.transactions"><div class="tx-heading"><span :class="t.status==='success'?'good':'bad'">{{t.status==='success'?'✓':'×'}} {{t.status}}</span><code>{{t.hash}}</code></div><div class="tx-meta"><span>Actor {{t.actor}}</span><span>To {{t.to??'Contract creation'}}</span><span>Gas {{t.gasUsed}}</span></div><div class="event-tags"><span v-for="e in t.events">{{e.event}}</span></div><details><summary>{{t.events.length}} decoded events · {{t.changes.length}} asset movements</summary><h3>Net balance changes</h3><div class="movement" v-for="d in t.balanceDeltas"><code>{{short(d.address)}}</code><span>{{d.asset==='ETH'?'ETH (includes gas)':short(d.asset)}}{{d.positionId?` / ${short(d.positionId)}`:''}}</span><b>{{BigInt(d.delta)>0n?'+':''}}{{amount(d.delta)}}</b></div><h3>Asset transfers</h3><div class="movement" v-for="c in t.changes"><code>{{short(c.asset)}}{{c.positionId?` / position ${short(c.positionId)}`:''}}</code><span>{{short(c.from)}} → {{short(c.to)}}</span><b>{{amount(c.amount)}}</b></div><pre>{{stringify(t.events)}}</pre></details></div></article></section>
 </main><div v-else class="loading">Connecting to the Agora research chain…</div><footer>AGORA / OPEN MATHEMATICS <span>Gnosis CTF + FPMM · Immutable revenue epochs · Safe governance</span><b>Test assets only</b></footer>
 </div>
</div>
</template>
